#!/usr/bin/env python3
import sys, os, re, io, csv, gzip, json, datetime as dt
import xml.etree.ElementTree as ET
from fractions import Fraction
from decimal import Decimal, ROUND_HALF_UP

UNITS = {'kg': Fraction(1), 'g': Fraction(1, 1000),
         'lb': Fraction('0.45359237'), 'oz': Fraction('0.028349523125')}
ORDER = ['central', 'south', 'east', 'river', 'north', 'west', 'harbor', 'lakeside']
DELIM = {'east': ',', 'lakeside': ',', 'harbor': '|', 'river': '\t', 'west': ';'}
COLS = {
    'east': {'id', 'type', 'shipped', 'gross', 'net', 'status', 'note'},
    'lakeside': {'id', 'kind', 'booked', 'shipped', 'gross_kg', 'net_kg', 'status'},
    'harbor': {'rec', 'ref', 'date', 'weight', 'state'},
    'river': {'t', 'ref', 'shipped', 'weight', 'status'},
    'west': {'id', 'typ', 'shipped', 'weight', 'status', 'note'},
}
BASE_DATE = {'east': 'YMD', 'lakeside': 'iso', 'harbor': 'iso', 'river': 'MM/DD/YYYY', 'west': 'DD.MM.YYYY'}
BASE_UNIT = {'east': 'kg', 'lakeside': 'kg', 'harbor': 'kg', 'river': 'kg', 'west': 'kg', 'north': 'kg', 'central': 'kg'}
CODES = {'D': 'delivered', 'L': 'delivered_late', 'C': 'cancelled', 'R': 'returned', 'H': 'held'}
HSTATE = {'DLV': 'delivered', 'DLL': 'delivered_late', 'CAN': 'cancelled', 'RET': 'returned', 'HLD': 'held'}
MONTHS = {m: i + 1 for i, m in enumerate(['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'])}
ID_RE = re.compile(r'^\s*SH\W*0*(\d+)\s*$', re.I)


def read_text(path):
    b = open(path, 'rb').read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    return b


def decode(b):
    if b[:3] == b'\xef\xbb\xbf':
        return b[3:].decode('utf-8')
    if b[:2] == b'\xff\xfe':
        return b[2:].decode('utf-16-le')
    if b[:2] == b'\xfe\xff':
        return b[2:].decode('utf-16-be')
    enc = 'utf-8'
    head = b[:2000].decode('latin-1')
    for l in head.split('\n')[:10]:
        m = re.match(r'#\s*charset\s*:\s*(\S+)', l)
        if m:
            enc = m.group(1)
            break
    try:
        return b.decode(enc)
    except (LookupError, UnicodeDecodeError):
        return b.decode('cp1252', errors='replace')


def norm_status(s):
    return re.sub(r'[\s\-]+', '_', (s or '').strip().lower())


def norm_type(t):
    t = (t or '').strip().lower()
    if t.startswith('v'):
        return 'void'
    if t.startswith('c') or t.startswith('a'):
        return 'correction'
    return 'new'


def to_frac(s, decimal_comma):
    s = s.strip().replace(' ', '')
    if decimal_comma:
        s = s.replace('.', '').replace(',', '.')
    else:
        s = s.replace(',', '')
    return Fraction(Decimal(s))


def parse_weight(raw, depot, own_unit, directive_unit):
    raw = (raw or '').strip()
    m = re.match(r'^([\d.,]+)\s*([A-Za-z]+)?$', raw)
    if not m:
        return None
    unit = (m.group(2) or '').lower() or own_unit or directive_unit or BASE_UNIT[depot]
    if unit not in UNITS:
        unit = BASE_UNIT[depot]
    return to_frac(m.group(1), depot == 'west') * UNITS[unit]


def first_word_unit(v):
    w = re.match(r'\s*([A-Za-z]+)', v or '')
    if w and w.group(1).lower() in UNITS:
        return w.group(1).lower()
    return None


def parse_dt(s, form):
    """Return (year, month) in UTC of the date/time string."""
    s = s.strip()
    off = dt.timedelta(0)
    tm = None
    m = re.match(r'^(.*?)(?:[T ](\d{1,2}):(\d{2})(?::(\d{2})(?:\.\d+)?)?\s*(Z|[+-]\d{2}:?\d{2})?)$', s)
    datepart = s
    if m and re.search(r'\d', m.group(1)):
        datepart = m.group(1).strip()
        tm = (int(m.group(2)), int(m.group(3)), int(m.group(4) or 0))
        z = m.group(5)
        if z and z != 'Z':
            sign = 1 if z[0] == '+' else -1
            d = z[1:].replace(':', '')
            off = sign * dt.timedelta(hours=int(d[:2]), minutes=int(d[2:]))
    f = (form or '').strip().lower()
    d = None
    mm = re.match(r'^(\d{1,2})\s+([A-Za-z]{3})[a-z]*\.?,?\s+(\d{4})$', datepart)
    if mm:
        d = dt.date(int(mm.group(3)), MONTHS[mm.group(2).lower()], int(mm.group(1)))
    elif re.match(r'^\d{4}-\d{2}-\d{2}$', datepart) and f not in ('dmy',):
        d = dt.date.fromisoformat(datepart)
    elif re.match(r'^\d{8}$', datepart):
        d = dt.date(int(datepart[:4]), int(datepart[4:6]), int(datepart[6:]))
    elif re.match(r'^\d{7}$', datepart):
        d = dt.date(int(datepart[:4]), 1, 1) + dt.timedelta(days=int(datepart[4:]) - 1)
    elif f == 'serial' or re.match(r'^\d{5}(\.\d+)?$', datepart):
        d = dt.date(1899, 12, 31) + dt.timedelta(days=int(float(datepart)))
        if int(float(datepart)) >= 60:
            d = dt.date(1899, 12, 30) + dt.timedelta(days=int(float(datepart)))
    else:
        p = re.split(r'[-/.]', datepart)
        if len(p) != 3:
            raise ValueError('bad date %r' % s)
        a, b, c = [int(x) for x in p]
        if len(p[0]) == 4:
            d = dt.date(a, b, c)
        elif f in ('mm/dd/yyyy', 'mdy'):
            d = dt.date(c, a, b)
        else:  # DMY, DD/MM/YYYY, DD.MM.YYYY
            d = dt.date(c, b, a)
    if tm:
        x = dt.datetime.combine(d, dt.time(*tm)) - off
        d = x.date()
    return d.year, d.month


# ---------- record readers; each yields dicts: id, type, ym, weight(Fraction), status
def make(rid, typ, shipped, weight, status, form=None):
    m = ID_RE.match(rid or '')
    if not m:
        return None
    r = {'num': int(m.group(1)), 'type': typ}
    if typ != 'void':
        r['ym'] = parse_dt(shipped, form)
        r['weight'] = weight
        r['status'] = status
    return r


def read_delimited(depot, text):
    delim = DELIM[depot]
    cols = COLS[depot]
    lines = text.split('\n')
    seq = None
    dirs = {}
    header = None
    out = []
    i = 0
    while i < len(lines):
        line = lines[i].rstrip('\r')
        i += 1
        if not line.strip():
            continue
        if line.startswith('#'):
            m = re.match(r'#\s*([^:=]+?)\s*:\s*(.*)$', line)
            if m:
                k = re.sub(r'\s+', ' ', m.group(1).lower())
                dirs[k] = m.group(2).strip()
                if k == 'seq':
                    seq = int(dirs[k])
            m = re.search(r'seq=(\d+)', line)
            if m and seq is None:
                seq = int(m.group(1))
            continue
        if delim == ',':
            while line.count('"') % 2 == 1 and i < len(lines):
                line += '\n' + lines[i].rstrip('\r')
                i += 1
            row = next(csv.reader([line], delimiter=',', quotechar='"'))
        else:
            row = line.split(delim)
        stripped = [x.strip().lower() for x in row]
        if stripped and all(x in cols for x in stripped):
            header = stripped
            continue
        if header is None:
            continue
        own_unit = None
        if len(row) > len(header):
            for j, x in enumerate(row):
                if x.strip().lower() in UNITS:
                    own_unit = x.strip().lower()
                    row = row[:j] + row[j + 1:]
                    break
        row = row + [''] * (len(header) - len(row))
        d = dict(zip(header, row))
        form = dirs.get('dates') or dirs.get('date format') or BASE_DATE[depot]
        form = form.split()[0]
        dunit = first_word_unit(dirs.get('unit') or dirs.get('weight unit'))
        try:
            if depot == 'east':
                typ = norm_type(d['type']); rid = d['id']
                r = make(rid, typ, d['shipped'], None, norm_status(d['status']), form)
                if r and typ != 'void':
                    r['weight'] = parse_weight(d['gross'], depot, own_unit, dunit)
            elif depot == 'lakeside':
                typ = norm_type(d['kind'])
                r = make(d['id'], typ, d['shipped'], None, norm_status(d['status']), form)
                if r and typ != 'void':
                    r['weight'] = parse_weight(d['gross_kg'], depot, 'kg', None)
            elif depot == 'harbor':
                typ = norm_type(d['rec'])
                st = d['state'].strip().upper()
                r = make(d['ref'], typ, d['date'], None, HSTATE.get(st, norm_status(st)), form)
                if r and typ != 'void':
                    r['weight'] = parse_weight(d['weight'], depot, own_unit, dunit)
            elif depot == 'river':
                typ = norm_type(d['t'])
                r = make(d['ref'], typ, d['shipped'], None, norm_status(d['status']), form)
                if r and typ != 'void':
                    r['weight'] = parse_weight(d['weight'], depot, own_unit, dunit)
            else:
                typ = norm_type(d['typ'])
                r = make(d['id'], typ, d['shipped'], None, norm_status(d['status']), form)
                if r and typ != 'void':
                    r['weight'] = parse_weight(d['weight'], depot, own_unit, dunit)
        except (ValueError, ArithmeticError, KeyError) as e:
            sys.stderr.write('skip row %r: %s\n' % (row, e))
            continue
        if r:
            out.append(r)
    return seq, out


def read_north(text):
    seq = None
    out = []
    for line in text.split('\n'):
        line = line.strip()
        if not line:
            continue
        try:
            v = json.loads(line)
        except ValueError:
            continue
        objs = v if isinstance(v, list) else [v]
        for o in objs:
            if not isinstance(o, dict):
                continue
            if 'meta' in o and isinstance(o['meta'], dict):
                if 'seq' in o['meta']:
                    seq = int(o['meta']['seq'])
                continue
            typ = norm_type(o.get('kind'))
            if 'kind' in o and str(o['kind']).lower() == 'new':
                typ = 'new'
            w = None
            for k, val in o.items():
                m = re.match(r'^weight_(kg|g|lb|oz)$', k, re.I)
                if m:
                    w = Fraction(Decimal(str(val))) * UNITS[m.group(1).lower()]
            try:
                r = make(str(o.get('id', '')), typ, str(o.get('shipped_at', '')), w, norm_status(o.get('status')))
            except (ValueError, ArithmeticError) as e:
                sys.stderr.write('skip %r\n' % (o,))
                continue
            if r:
                out.append(r)
    return seq, out


def read_central(b):
    root = ET.fromstring(b)
    seq = int(root.get('seq')) if root.get('seq') else None
    runit = (root.get('weight-unit') or 'kg').strip().lower()
    out = []
    for e in root.iter('shipment'):
        def val(n):
            if e.get(n) is not None:
                return e.get(n)
            c = e.find(n)
            return c.text if c is not None and c.text else None
        typ = norm_type(e.get('type'))
        w = None
        we = e.find('weight')
        if we is not None and we.text:
            u = (we.get('unit') or runit).lower()
            w = to_frac(we.text, False) * UNITS.get(u, 1)
        elif e.get('weight'):
            w = to_frac(e.get('weight'), False) * UNITS.get((e.get('unit') or runit).lower(), 1)
        try:
            r = make(e.get('id'), typ, val('shipped') or '', w, norm_status(val('status')))
        except (ValueError, ArithmeticError):
            continue
        if r:
            out.append(r)
    return seq, out


def read_south(text):
    seq = None
    layout = None
    out = []
    LAY = {42: 'FW1', 43: 'FW2', 41: 'FW3'}
    for line in text.split('\n'):
        line = line.rstrip('\r')
        if '\f' in line or not line.strip():
            continue
        if line.startswith('#'):
            m = re.match(r'#LAYOUT\s+(\S+)', line)
            if m:
                layout = m.group(1).upper()
            m = re.match(r'#SEQ\s+(\d+)', line)
            if m:
                seq = int(m.group(1))
            continue
        lay = LAY.get(len(line))
        if lay is None:
            continue
        # layout in force has its own record length; otherwise length decides
        if lay == 'FW1':
            rid, t, sh, wt, st = line[0:9], line[9], line[10:17], line[17:25], line[25]
            ws = Fraction(int(wt)) * UNITS['g']
        elif lay == 'FW2':
            t, rid, sh, wt, st = line[0], line[1:10], line[10:18], line[18:26], line[26]
            ws = Fraction(int(wt), 100)
        else:
            rid, sh, t, wt, st = line[0:9], line[9:16], line[16], line[17:24], line[24]
            ws = Fraction(int(wt), 10) * UNITS['lb']
        typ = norm_type(t)
        try:
            r = make(rid, typ, sh.strip() if typ != 'void' else '', ws, CODES.get(st.upper(), st))
        except (ValueError, ArithmeticError):
            continue
        if r:
            out.append(r)
    return seq, out


def main():
    data_dir, out_file = sys.argv[1], sys.argv[2]
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        p = os.path.join(data_dir, name)
        if not os.path.isfile(p):
            continue
        depot = name.split('-')[0]
        b = read_text(p)
        if depot == 'central':
            seq, recs = read_central(b)
        else:
            text = decode(b)
            if depot == 'north':
                seq, recs = read_north(text)
            elif depot == 'south':
                seq, recs = read_south(text)
            elif depot in DELIM:
                seq, recs = read_delimited(depot, text)
            else:
                seq, recs = None, []
        exports.setdefault(depot, []).append((seq if seq is not None else -1, name, recs))

    corrections = resends = 0
    current = {}
    for depot, lst in exports.items():
        cur = {}
        for seq, name, recs in sorted(lst, key=lambda x: (x[0], x[1])):
            for r in recs:
                n = r['num']
                if r['type'] == 'new':
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = r
                elif r['type'] == 'correction':
                    cur[n] = r
                    corrections += 1
                else:
                    cur.pop(n, None)
                    corrections += 1
        current[depot] = cur

    depots = {d: [0, Fraction(0)] for d in exports}
    months = {}
    handovers = 0
    seen = {}
    rank = {d: i for i, d in enumerate(ORDER)}
    for d, cur in current.items():
        for n in cur:
            seen.setdefault(n, []).append(d)
    for n, ds in seen.items():
        if len(ds) > 1:
            handovers += 1
        d = min(ds, key=lambda x: rank.get(x, 99))
        r = current[d][n]
        if r['status'] in ('delivered', 'delivered_late') and r['weight'] is not None:
            depots[d][0] += 1
            depots[d][1] += r['weight']
            ym = '%04d-%02d' % r['ym']
            m = months.setdefault(ym, [0, Fraction(0)])
            m[0] += 1
            m[1] += r['weight']

    def rnd(f):
        q = (Decimal(f.numerator) / Decimal(f.denominator)) if False else None
        x = f * 100
        n = (x.numerator * 2 + x.denominator) // (x.denominator * 2)
        return float(Decimal(n) / 100)

    res = {
        'depots': {d: {'shipments': v[0], 'total_kg': rnd(v[1])} for d, v in sorted(depots.items())},
        'months': {k: {'shipments': v[0], 'total_kg': rnd(v[1])} for k, v in sorted(months.items())},
        'corrections_applied': corrections,
        'resends_dropped': resends,
        'handovers': handovers,
    }
    with open(out_file, 'w') as f:
        json.dump(res, f, indent=2)


main()
